    return `Renda estimada: ${reais(l.renda_mediana_brl)} · Homicídios no município: ${fmt(l.homicidios_taxa_100mil)} por 100 mil`;
  }
  window.PolitizeTerritorio = { painel, resumo, reais, perc, fmt };
})();
