cat > docs/assets/politize_se/territorio.css <<'EOF'
/* Painéis territoriais: a mesma linguagem editorial nas fichas e no mapa. */
.territorio{--teal:#17635e;--rust:#944126;--t-paper:#fffdf7;color:#202820;background:var(--t-paper);border:1px solid #c9cbbd;margin:24px 0;padding:24px;border-radius:12px;max-width:100%;text-align:left}
.territorio *{box-sizing:border-box}
.territorio .territorio-eyebrow{font:500 11px/1.5 "IBM Plex Mono",monospace;letter-spacing:.09em;text-transform:uppercase;color:#536156;margin:0 0 8px}
.territorio .territorio-cab h2{font:700 clamp(23px,3vw,34px)/1.13 Georgia,serif;margin:0 0 10px;color:#202820}
.territorio .territorio-cab>p:last-child{max-width:78ch;font-size:16px;line-height:1.45;margin:0 0 22px}
