.territorio .territorio-card h3{font:700 21px/1.2 Georgia,serif;margin:0 0 12px;color:#202820}
.territorio .territorio-numero{font:500 clamp(32px,4vw,46px)/1.1 "IBM Plex Mono",monospace;letter-spacing:-.055em;margin:8px 0;color:var(--teal)}
.territorio-seguranca .territorio-numero{color:var(--rust)}
.territorio .territorio-numero small{font:400 13px/1.4 "IBM Plex Sans Condensed",sans-serif;letter-spacing:0;white-space:nowrap}
.territorio .territorio-sub{font:400 12px/1.5 "IBM Plex Mono",monospace;color:#536156;margin:0 0 20px}
