.territorio .territorio-extremos{display:flex;justify-content:space-between;font-size:12px;margin:9px 0 14px;color:#655347}
.territorio .territorio-documentado{font-size:19px;font-weight:700;line-height:1.3}
.territorio summary{cursor:pointer;font-size:14px;font-weight:600;min-height:44px;padding:12px 0}
